import React, { useState } from 'react';
import {
  Badge,
  Box,
  Button as MUIButton,
  Divider,
  Drawer,
  IconButton,
  List,
  ListItem,
  ListItemAvatar,
  ListItemText,
  Typography,
  Avatar,
  Chip,
  Tooltip,
  Slide,
  Fade
} from '@mui/material';
import { ShoppingCart, Close, Add, Remove, Delete, LocalOffer } from '@mui/icons-material';
import { useCart } from '../context/CartContext';
import { useNavigate } from 'react-router-dom';

const CarBuy = () => {
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();
  
  const { 
    cartItems, 
    totalItems, 
    removeFromCart, 
    updateQuantity,
    calculateTotal 
  } = useCart();

  const handleProceedToCheckout = () => {
    const cartData = cartItems.map(item => ({
      id: item.id,
      isVariation: item.isVariation,
      variationId: item.isVariation ? item.variacion.id : null,
      quantity: item.quantity,
      price: item.price
    }));

    navigate('/crear-venta', { state: { cartItems: cartData } });
    setOpen(false);
  };

  return (
    <>
      {/* Icono del carrito mejorado */}
      <Tooltip title="Carrito de compras" placement="bottom">
        <IconButton 
          color="inherit" 
          onClick={() => setOpen(true)}
          sx={{
            color: '#1a1a1a',
            borderRadius: '12px',
            padding: '10px',
            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
            '&:hover': {
              backgroundColor: 'rgba(0, 0, 0, 0.08)',
              transform: 'scale(1.05)',
              boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)'
            }
          }}
        >
          <Badge 
            badgeContent={totalItems} 
            color="error"
            sx={{
              '& .MuiBadge-badge': {
                right: -3,
                top: 13,
                border: '2px solid white',
                padding: '0 6px',
                fontSize: '0.75rem',
                fontWeight: 'bold',
                minWidth: '20px',
                height: '20px',
                borderRadius: '10px',
                background: '#FF6B00',
                boxShadow: '0 2px 6px rgba(255, 107, 0, 0.4)',
                animation: totalItems > 0 ? 'pulse 2s infinite' : 'none',
                '@keyframes pulse': {
                  '0%': { transform: 'scale(1)' },
                  '50%': { transform: 'scale(1.1)' },
                  '100%': { transform: 'scale(1)' }
                }
              }
            }}
          >
            <ShoppingCart sx={{ fontSize: '24px' }} />
          </Badge>
        </IconButton>
      </Tooltip>

      {/* Drawer del carrito rediseñado */}
      <Drawer
        anchor="right"
        open={open}
        onClose={() => setOpen(false)}
        PaperProps={{
          sx: { 
            width: '100%', 
            maxWidth: 440, 
            background: 'linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%)',
            backdropFilter: 'blur(20px)',
            '&.MuiDrawer-paper': {
              boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
              borderLeft: 'none',
              borderRadius: '20px 0 0 20px'
            }
          }
        }}
        transitionDuration={{ enter: 400, exit: 300 }}
      >
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
          {/* Header mejorado */}
          <Box sx={{ 
            p: 3,
            background: '#FF6B00',
            color: 'white',
            position: 'relative',
            overflow: 'hidden',
            '&::before': {
              content: '""',
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              background: 'url("data:image/svg+xml,%3Csvg width="40" height="40" viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg  "%3E%3Cg fill="white" fill-opacity="0.05"%3E%3Cpath d="M20 20c0 11.046-8.954 20-20 20v20h40V20H20z"/%3E%3C/g%3E%3C/svg%3E") repeat',
              opacity: 0.1
            }
          }}>
            <Box sx={{ 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center',
              position: 'relative',
              zIndex: 1
            }}>
              <Box>
                <Typography variant="h5" component="div" sx={{ 
                  fontWeight: 'bold',
                  mb: 0.5,
                  textShadow: '0 2px 4px rgba(0,0,0,0.2)'
                }}>
                  Mi Carrito
                </Typography>
                <Typography variant="body2" sx={{ 
                  opacity: 0.9,
                  fontSize: '0.875rem'
                }}>
                  {totalItems} {totalItems === 1 ? 'producto' : 'productos'} seleccionados
                </Typography>
              </Box>
              <IconButton 
                onClick={() => setOpen(false)}
                sx={{
                  color: 'white',
                  backgroundColor: 'rgba(255, 255, 255, 0.1)',
                  backdropFilter: 'blur(10px)',
                  '&:hover': {
                    backgroundColor: 'rgba(255, 255, 255, 0.2)',
                    transform: 'rotate(90deg)'
                  },
                  transition: 'all 0.3s ease'
                }}
              >
                <Close />
              </IconButton>
            </Box>
          </Box>

          {/* Contenido principal */}
          <Box sx={{ flex: 1, overflow: 'auto' }}>
            {cartItems.length === 0 ? (
              <Fade in={cartItems.length === 0} timeout={600}>
                <Box sx={{ 
                  display: 'flex', 
                  flexDirection: 'column', 
                  alignItems: 'center',
                  justifyContent: 'center',
                  height: '100%',
                  p: 4,
                  textAlign: 'center'
                }}>
                  <Box sx={{
                    position: 'relative',
                    mb: 3
                  }}>
                    <ShoppingCart sx={{ 
                      fontSize: 100, 
                      color: '#e2e8f0',
                      filter: 'drop-shadow(0 4px 6px rgba(0, 0, 0, 0.1))'
                    }} />
                    <Box sx={{
                      position: 'absolute',
                      top: '50%',
                      left: '50%',
                      transform: 'translate(-50%, -50%)',
                      width: '120px',
                      height: '120px',
                      border: '3px dashed #cbd5e1',
                      borderRadius: '50%',
                      animation: 'rotate 10s linear infinite',
                      '@keyframes rotate': {
                        '0%': { transform: 'translate(-50%, -50%) rotate(0deg)' },
                        '100%': { transform: 'translate(-50%, -50%) rotate(360deg)' }
                      }
                    }} />
                  </Box>
                  <Typography variant="h6" sx={{ 
                    color: '#64748b',
                    fontWeight: 'medium',
                    mb: 1
                  }}>
                    Tu carrito está vacío
                  </Typography>
                  <Typography variant="body2" sx={{ 
                    color: '#94a3b8',
                    mb: 3,
                    maxWidth: '200px'
                  }}>
                    Agrega algunos productos increíbles para comenzar
                  </Typography>
                  <MUIButton 
                    variant="contained" 
                    sx={{ 
                      background: 'linear-gradient(45deg, #667eea, #764ba2)',
                      color: 'white',
                      px: 4,
                      py: 1.5,
                      borderRadius: '25px',
                      textTransform: 'none',
                      fontWeight: 'medium',
                      boxShadow: '0 8px 25px rgba(102, 126, 234, 0.3)',
                      '&:hover': {
                        background: 'linear-gradient(45deg, #5a6fd8, #6a42a0)',
                        transform: 'translateY(-2px)',
                        boxShadow: '0 12px 35px rgba(102, 126, 234, 0.4)'
                      },
                      transition: 'all 0.3s ease'
                    }}
                    onClick={() => setOpen(false)}
                  >
                    Continuar comprando
                  </MUIButton>
                </Box>
              </Fade>
            ) : (
              <Box sx={{ p: 2 }}>
                <List sx={{ '& .MuiListItem-root': { mb: 1 } }}>
                  {cartItems.map((item, index) => (
                    <Slide 
                      key={item.isVariation ? `${item.id}-${item.variacion?.id}` : item.id}
                      direction="left"
                      in={true}
                      timeout={300 + index * 100}
                    >
                      <Box sx={{
                        backgroundColor: 'white',
                        borderRadius: '16px',
                        boxShadow: '0 4px 20px rgba(0, 0, 0, 0.08)',
                        mb: 2,
                        overflow: 'hidden',
                        border: '1px solid rgba(0, 0, 0, 0.04)',
                        transition: 'all 0.3s ease',
                        '&:hover': {
                          transform: 'translateY(-2px)',
                          boxShadow: '0 8px 30px rgba(0, 0, 0, 0.12)'
                        }
                      }}>
                        <ListItem
                          secondaryAction={
                            <IconButton 
                              edge="end" 
                              onClick={() => 
                                removeFromCart(
                                  item.id, 
                                  item.isVariation, 
                                  item.isVariation ? item.variacion.id : null
                                )
                              }
                              sx={{
                                color: '#dc2626',
                                backgroundColor: 'rgba(220, 38, 38, 0.1)',
                                '&:hover': {
                                  color: '#b32323',
                                  backgroundColor: 'rgba(220, 38, 38, 0.2)',
                                  transform: 'scale(1.1)'
                                },
                                transition: 'all 0.2s ease'
                              }}
                            >
                              <Delete fontSize="small" />
                            </IconButton>
                          }
                          sx={{
                            alignItems: 'flex-start',
                            p: 2.5
                          }}
                        >
                          <ListItemAvatar>
                            <Avatar 
                              src={item.image} 
                              alt={item.nombre}
                              variant="rounded"
                              sx={{ 
                                width: 70, 
                                height: 70, 
                                mr: 2,
                                borderRadius: '12px',
                                boxShadow: '0 4px 12px rgba(0, 0, 0, 0.15)',
                                border: '2px solid white'
                              }}
                            />
                          </ListItemAvatar>
                          <ListItemText
                            primary={
                              <Box>
                                <Typography variant="subtitle1" sx={{ 
                                  fontWeight: 'bold',
                                  color: '#1e293b',
                                  mb: 0.5
                                }}>
                                  {item.nombre}
                                </Typography>
                                {item.isVariation && (
                                  <Box sx={{ display: 'flex', gap: 1, mb: 1, flexWrap: 'wrap' }}>
                                    {item.color && (
                                      <Chip 
                                        label={item.color}
                                        icon={<Box sx={{ width: 8, height: 8, borderRadius: '50%', backgroundColor: item.color.toLowerCase() }} />}
                                        size="small" 
                                        sx={{ 
                                          backgroundColor: '#f1f5f9',
                                          color: '#475569',
                                          fontWeight: 'medium',
                                          '&:hover': {
                                            backgroundColor: '#e2e8f0'
                                          }
                                        }}
                                      />
                                    )}
                                    {item.model && (
                                      <Chip 
                                        label={item.model}
                                        size="small" 
                                        sx={{ 
                                          backgroundColor: '#fef3c7',
                                          color: '#d97706',
                                          fontWeight: 'medium'
                                        }}
                                      />
                                    )}
                                  </Box>
                                )}
                                {item.warranty && (
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mb: 0.5 }}>
                                    <LocalOffer sx={{ fontSize: 14, color: '#FF6B00' }} />
                                    <Typography variant="caption" sx={{ 
                                      color: '#FF6B00',
                                      fontWeight: 'medium'
                                    }}>
                                      Garantía: {item.warranty}
                                    </Typography>
                                  </Box>
                                )}
                                {item.gift && (
                                  <Typography variant="caption" display="block" sx={{ 
                                    color: '#FF6B00',
                                    fontWeight: 'medium',
                                    fontSize: '0.75rem'
                                  }}>
                                    🎁 Regalo: {item.gift}
                                  </Typography>
                                )}
                              </Box>
                            }
                            secondary={
                              <Box sx={{ 
                                display: 'flex', 
                                alignItems: 'center',
                                justifyContent: 'space-between',
                                mt: 2
                              }}>
                                <Box sx={{ 
                                  display: 'flex', 
                                  alignItems: 'center',
                                  backgroundColor: '#f8fafc',
                                  borderRadius: '12px',
                                  border: '1px solid #e2e8f0'
                                }}>
                                  <IconButton 
                                    size="small" 
                                    onClick={() => 
                                      updateQuantity(
                                        item.id,
                                        item.isVariation,
                                        item.isVariation ? item.variacion.id : null,
                                        item.quantity - 1
                                      )
                                    }
                                    sx={{
                                      color: '#64748b',
                                      '&:hover': {
                                        color: '#1e293b',
                                        backgroundColor: '#e2e8f0'
                                      }
                                    }}
                                  >
                                    <Remove fontSize="small" />
                                  </IconButton>
                                  <Typography variant="body1" sx={{ 
                                    mx: 2,
                                    fontWeight: 'bold',
                                    color: '#1e293b',
                                    minWidth: '20px',
                                    textAlign: 'center'
                                  }}>
                                    {item.quantity}
                                  </Typography>
                                  <IconButton 
                                    size="small" 
                                    onClick={() => 
                                      updateQuantity(
                                        item.id,
                                        item.isVariation,
                                        item.isVariation ? item.variacion.id : null,
                                        item.quantity + 1
                                      )
                                    }
                                    sx={{
                                      color: '#64748b',
                                      '&:hover': {
                                        color: '#1e293b',
                                        backgroundColor: '#e2e8f0'
                                      }
                                    }}
                                  >
                                    <Add fontSize="small" />
                                  </IconButton>
                                </Box>
                                <Typography variant="h6" sx={{ 
                                  fontWeight: 'bold',
                                  color: '#059669',
                                  textShadow: '0 1px 2px rgba(5, 150, 105, 0.1)'
                                }}>
                                  ${(parseFloat(item.price) * item.quantity).toFixed(2)}
                                </Typography>
                              </Box>
                            }
                          />
                        </ListItem>
                      </Box>
                    </Slide>
                  ))}
                </List>
              </Box>
            )}
          </Box>

          {/* Footer con total y botón de pago */}
          {cartItems.length > 0 && (
            <Box sx={{ 
              p: 3,
              background: 'white',
              borderTop: '1px solid #e2e8f0',
              boxShadow: '0 -4px 20px rgba(0, 0, 0, 0.1)'
            }}>
              <Box sx={{
                backgroundColor: '#f8fafc',
                borderRadius: '16px',
                p: 2.5,
                mb: 2,
                border: '1px solid #e2e8f0'
              }}>
                <Box sx={{ 
                  display: 'flex', 
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  mb: 1
                }}>
                  <Typography variant="body1" sx={{ 
                    color: '#64748b',
                    fontWeight: 'medium'
                  }}>
                    Subtotal ({totalItems} {totalItems === 1 ? 'producto' : 'productos'}):
                  </Typography>
                  <Typography variant="h5" sx={{ 
                    fontWeight: 'bold',
                    color: '#1e293b'
                  }}>
                    ${calculateTotal().toFixed(2)}
                  </Typography>
                </Box>
                <Typography variant="caption" sx={{ 
                  color: '#94a3b8',
                  fontSize: '0.75rem'
                }}>
                  Los gastos de envío se calcularán en el checkout
                </Typography>
              </Box>

              <MUIButton
                fullWidth
                variant="contained"
                size="large"
                onClick={handleProceedToCheckout}
                sx={{
                  background: '#000000',
                  color: 'white',
                  py: 2,
                  borderRadius: '16px',
                  textTransform: 'none',
                  fontSize: '1.1rem',
                  fontWeight: 'bold',
                  boxShadow: '0 8px 25px rgba(0, 0, 0, 0.3)',
                  '&:hover': {
                    background: '#1a1a1a',
                    transform: 'translateY(-2px)',
                    boxShadow: '0 12px 35px rgba(0, 0, 0, 0.4)'
                  },
                  transition: 'all 0.3s ease'
                }}
              >
                Datos de Compra
              </MUIButton>
            </Box>
          )}
        </Box>
      </Drawer>
    </>
  );
};

export default CarBuy;